```dart
import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitEarnedOrLoss;

  Transaction({required this.coinName, required this.datetime, required this.profitEarnedOrLoss});
}

List<Transaction> sortTransactions(List<Transaction> transactions) {
  return transactions.sort((a, b) => b.profitEarnedOrLoss.compareTo(a.profitEarnedOrLoss));
}

List<String> getTopCoinsWithHighestAverageProfit(List<Transaction> transactions, int count) {
  var sortedTransactions = sortTransactions(transactions);
  var groupedTransactions = sortedTransactions.groupBy((transaction) => transaction.coinName);
  var averageProfits = groupedTransactions.map((key, value) {
    return MapEntry(key, value.map((transaction) => transaction.profitEarnedOrLoss).reduce((a, b) => a + b) / value.length);
  });
  return averageProfits.entries.skip(count - 1).take(count).map((e) => e.key).toList();
}

List<String> getTopCoinsWithHighestAverageLoss(List<Transaction> transactions, int count) {
  var sortedTransactions = sortTransactions(transactions);
  var groupedTransactions = sortedTransactions.groupBy((transaction) => transaction.coinName);
  var averageLosses = groupedTransactions.map((key, value) {
    return MapEntry(key, value.map((transaction) => -transaction.profitEarnedOrLoss).reduce((a, b) => a + b) / value.length);
  });
  return averageLosses.entries.skip(count - 1).take(count).map((e) => e.key).toList();
}
```

