<?php
// Database connection details
$servername = "localhost";
$username = "username";
$password = "password";
$dbname = "database_name";

// Create connection
$conn = new mysqli($servername, $username, $password, $dbname);

// Check connection
if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}

// Query to find loyal customers
$sql = "SELECT customer_id, COUNT(*) as purchase_count
        FROM transactions
        WHERE product_id = 'specific_product_id' AND purchase_date BETWEEN DATE_SUB(CURDATE(), INTERVAL 1 WEEK) AND CURDATE()
        GROUP BY customer_id
        HAVING purchase_count >= 3;";

// Execute query and fetch results
$result = $conn->query($sql);

// Display results
if ($result->num_rows > 0) {
    // output data of each row
    while($row = $result->fetch_assoc()) {
        echo "Customer ID: " . $row["customer_id"]. " - Purchase Count: " . $row["purchase_count"]. "<br>";
    }
} else {
    echo "0 results";
}

// Close connection
$conn->close();
?>
```

Replace `specific_product_id` with the actual product ID you want to search for. This code will retrieve all customers who have purchased the specified product at least three times within the last week. The result will be displayed in an array format, containing customer IDs and their corresponding purchase counts.

Here's the R code:

```R
# Function to check if all non-NA elements in a character vector can be converted to numeric
can_convert_to_numeric <- function(vec) {
  for (i in seq_along(vec)) {
    if (!is.na(vec[i]) && !is.numeric(as.numeric(vec[i]))) {
      return(FALSE)
    }
  }
  return(TRUE)
}

# Example usage
vec <- c("1", "2", "3", NA, "4")
if (can_convert_to_numeric(vec)) {
  print("All non-NA elements in vec can be converted to numeric.")
} else {
  print("Not all non-NA elements in vec can be converted to numeric.")
}
```

