% Encrypt patient data
data = 'John Doe';
encrypted_data = encrypt(data, 'AES-256-CBC', 'password');

% Store encrypted data in a secure database
database = 'patient_data.db';
insert(database, 'patient_id', 1, 'encrypted_data', encrypted_data);

% Access encrypted data
patient_id = 1;
encrypted_data = select(database, 'encrypted_data', 'patient_id', patient_id);
