    }

    if (catcherInTheRye.equals(book2)) {
        std::cout << "Catcher in the Rye and 1984 are identical." << std::endl;
    }

    if (book1.equals(book2)) {
        std::cout << "To Kill a Mockingbird and 1984 are identical." << std::endl;
    }

    return 0;
}
