  async get(key) {
    const result = await this.redis.get(key);
    return result;
  }

  async set(key, value, duration) {
    await this.redis.set(key, value, { EX: duration });
  }

  async del(key) {
    await this.redis.del(key);
  }
}

const redisClient = new RedisClient();

module.exports = redisClient;
```

